/** 
 * Evaluates the response data and generates a challenge. If a response is received from the client during the authentication process, this method is called to prepare an appropriate next challenge to submit to the client. The challenge is null if the authentication has succeeded and no more challenge data is to be sent to the client. It is non-null if the authentication must be continued by sending a challenge to the client, or if the authentication has succeeded but challenge data needs to be processed by the client. <tt>isComplete()</tt> should be called after each call to <tt>evaluateResponse()</tt>,to determine if any further response is needed from the client.
 * @param response The non-null (but possibly empty) response sentby the client.
 * @return The possibly null challenge to send to the client.It is null if the authentication has succeeded and there is no more challenge data to be sent to the client.
 * @exception SaslException If an error occurred while processingthe response or generating a challenge.
 */
@Override public byte[] evaluateResponse(final byte[] response) throws SaslException {
  byte[] challenge;
switch (state) {
case INITIAL:    challenge=generateServerFirstMessage(response);
  state=State.IN_PROGRESS;
break;
case IN_PROGRESS:challenge=generateServerFinalMessage(response);
state=State.COMPLETE;
break;
case COMPLETE:if (response == null || response.length == 0) {
challenge=new byte[0];
break;
}
default:throw new SaslException("No response expected in state " + state);
}
return challenge;
}
